/* The digital rain's glyphs (scr_kana.c, generated by tools/make_scr_kana.py): original half-width
 * katakana-style shapes and the digits, 5x7, each mirrored left to right. App/scr_silly.c draws them. Pure C. */
#ifndef SCR_KANA_H_INCLUDED
#define SCR_KANA_H_INCLUDED

#include <stdint.h>

#define SCR_KANA_W 5
#define SCR_KANA_H 7

extern const uint8_t scr_kana_count;                 /* the glyphs */
extern const uint8_t scr_kana_rows[][SCR_KANA_H];    /* their rows, bit 4 the leftmost column */

#endif
